describe('Navigation Between Home and Example Pages', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should navigate from home page to example page and back', () => {
    // Verify initial state on home page
    cy.get('[data-testid="welcome-heading"]').should('be.visible').should('contain', 'Welcome to the-internet');
    cy.get('[data-testid="available-examples-heading"]').should('be.visible').should('contain', 'Available Examples');

    // Click the A/B Testing link
    cy.get('[data-testid="ab-test-link"]').click();

    // Verify navigation to example page
    cy.url().should('include', '/abtest');
    cy.get('[data-testid="example-heading"]').should('be.visible').should('contain', 'A/B Testing Example');

    // Verify example page content
    cy.get('[data-testid="example-content"]').should('be.visible');
    cy.get('[data-testid="example-description"]').should('contain', 'This is an A/B testing example');

    // Navigate back to home page
    cy.get('[data-testid="back-link"]').click();

    // Verify return to home page
    cy.url().should('include', '/');
    cy.get('[data-testid="welcome-heading"]').should('be.visible').should('contain', 'Welcome to the-internet');
    cy.get('[data-testid="available-examples-heading"]').should('be.visible').should('contain', 'Available Examples');
  });

  it('should handle navigation to non-existent page gracefully', () => {
    // Verify initial state on home page
    cy.get('[data-testid="welcome-heading"]').should('be.visible').should('contain', 'Welcome to the-internet');

    // Click a broken link
    cy.get('[data-testid="broken-link"]').click();

    // Verify error state or fallback content
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Page not found');
    cy.get('[data-testid="fallback-content"]').should('be.visible').should('contain', 'Try a valid URL');

    // Verify navigation back to home page
    cy.get('[data-testid="back-link"]').click();

    // Verify return to home page
    cy.url().should('include', '/');
    cy.get('[data-testid="welcome-heading"]').should('be.visible').should('contain', 'Welcome to the-internet');
  });
});
